import neuronfrom  neuron.units import mV, msimport numpy as npfrom neuron import nimport textwrapimport bokeh.plotting as pltfrom bokeh.io import output_notebookimport matplotlib.pyplot as plt2# create a cellsoma = n.Section("soma")#topologyn.topology()#psectionsoma.psection()#dirdir(soma)print(textwrap.fill(", ".join(dir(n))))help(soma.connect)# insert ion channels - HH channelssoma.insert(n.hh)# test a clampiclamp = n.IClamp(soma(0.5))print([item for item in dir(iclamp) if not item.startswith("__")])soma.psection()# recordv = n.Vector().record(soma(0.5)._ref_v)  # Membrane potential vectort = n.Vector().record(n._ref_t)  # Time stamp vector#standard runn.load_file("stdrun.hoc")n.finitialize(-65 * mV) # initialize with -65 mv potentialn.continuerun(40 * ms) # continue for 40 msf = plt.figure(x_axis_label="t (ms)", y_axis_label="v (mV)")f.line(t, v, line_width=2)plt.show(f)plt2.figure()plt2.plot(t, v)plt2.xlabel("t (ms)")plt2.ylabel("v (mV)")plt2.show()# ok what happens if I try a more aggressive stimulation# Create a FRESH cellsoma2 = n.Section("soma")soma2.insert(n.hh)iclamp2 = n.IClamp(soma2(0.5))# You need to set these properties for iclamp2:iclamp2.delay = 5  # ms - when to start the stimulusiclamp2.dur = 2000  # ms - duration of stimulus (your 2 seconds)iclamp2.amp = 10  # nA - amplitude of current injectionv2 = n.Vector().record(soma2(0.5)._ref_v)  # Membrane potential vectort2 = n.Vector().record(n._ref_t)  # Time stamp vectorn.finitialize(-65 * mV) # initialize with -65 mv potentialn.continuerun(2000 * ms) # continue for 20000 msplt2.figure()plt2.plot(t2, v2)plt2.xlabel("t (ms)")plt2.ylabel("v (mV)")plt2.show()# so it still only does one action potential?